"""Command line entry point for consensus-protocol-lab."""

from __future__ import annotations

import argparse
import json
import math
import sys

from . import __version__
from .explore import run_explore
from .replay import run_replay
from .simulate import ScenarioError, run_simulation


def _reject_json_constant(value: str) -> None:
    raise ValueError(f"non-finite JSON number token: {value}")


def _reject_non_finite(value: object) -> None:
    """Reject every non-finite number anywhere in a decoded JSON tree.

    ``parse_constant`` refuses the bare NaN/Infinity/-Infinity literals, but a
    number whose exponent overflows float range (e.g. 1e1000) decodes to a
    non-finite float without ever being seen as a constant token; such values
    can hide at any depth (for example inside a client command), so the whole
    tree is checked after decoding. Object keys and the strings "NaN" /
    "Infinity" / "-Infinity" are ordinary strings and never rejected.
    """
    stack = [value]
    while stack:
        current = stack.pop()
        if isinstance(current, float):
            if not math.isfinite(current):
                raise ValueError(f"non-finite JSON number: {current!r}")
        elif isinstance(current, dict):
            stack.extend(current.values())
        elif isinstance(current, list):
            stack.extend(current)


def _load_strict_json(text: str) -> object:
    """Decode strict JSON: no NaN/Infinity/-Infinity tokens and no non-finite
    numbers anywhere in the tree."""
    raw = json.loads(text, parse_constant=_reject_json_constant)
    _reject_non_finite(raw)
    return raw


def _cmd_simulate(path: str) -> int:
    try:
        with open(path, "r", encoding="utf-8") as handle:
            text = handle.read()
    except OSError as exc:
        print(f"error: cannot read scenario file: {exc}", file=sys.stderr)
        return 2
    except UnicodeDecodeError:
        print(f"error: scenario file is not valid UTF-8: {path}", file=sys.stderr)
        return 2
    try:
        raw = _load_strict_json(text)
    except ValueError as exc:
        print(f"error: invalid JSON: {exc}", file=sys.stderr)
        return 2
    try:
        result = run_simulation(raw)
    except ScenarioError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def _cmd_explore(path: str) -> int:
    try:
        with open(path, "r", encoding="utf-8") as handle:
            text = handle.read()
    except OSError as exc:
        print(f"error: cannot read plan file: {exc}", file=sys.stderr)
        return 2
    except UnicodeDecodeError:
        print(f"error: plan file is not valid UTF-8: {path}", file=sys.stderr)
        return 2
    try:
        raw = _load_strict_json(text)
    except ValueError as exc:
        print(f"error: invalid JSON: {exc}", file=sys.stderr)
        return 2
    try:
        result = run_explore(raw)
    except ScenarioError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def _read_utf8_json(path: str, kind: str) -> tuple[bool, object]:
    """Read and decode a UTF-8 JSON file for replay. Returns (ok, value);
    on failure prints one ``error:`` line to stderr and returns (False,
    None). ``kind`` labels the file in the messages."""
    try:
        with open(path, "r", encoding="utf-8") as handle:
            text = handle.read()
    except OSError as exc:
        print(f"error: cannot read {kind} file: {exc}", file=sys.stderr)
        return False, None
    except UnicodeDecodeError:
        print(f"error: {kind} file is not valid UTF-8: {path}", file=sys.stderr)
        return False, None
    try:
        # Strict JSON boundary: refuse the non-standard NaN/Infinity tokens
        # and any non-finite number an exponent overflow could decode to,
        # anywhere in the tree.
        return True, _load_strict_json(text)
    except ValueError as exc:
        print(f"error: invalid JSON in {kind} file: {exc}", file=sys.stderr)
        return False, None


def _cmd_replay(scenario_path: str, result_path: str) -> int:
    ok, scenario_raw = _read_utf8_json(scenario_path, "scenario")
    if not ok:
        return 2
    ok, result_raw = _read_utf8_json(result_path, "result")
    if not ok:
        return 2
    # A non-object RESULT cannot carry the comparison contract (status is
    # reported as mismatched only when the top level is an object).
    if not isinstance(result_raw, dict):
        print("error: result file must contain a JSON object", file=sys.stderr)
        return 2
    try:
        report = run_replay(scenario_raw, result_raw)
    except ScenarioError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    # Compact, member order fixed by construction: byte-identical for
    # identical input.
    print(json.dumps(report, ensure_ascii=False, separators=(",", ":")))
    return 0 if report["status"] == "matched" else 1


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="consensus-protocol-lab", description="Deterministic simulation lab for Raft-style consensus protocols")
    sub = parser.add_subparsers(dest="command")
    sub.add_parser("version", help="print the current version")
    simulate = sub.add_parser("simulate", help="run a deterministic Raft leader-election simulation")
    simulate.add_argument("scenario", help="path to a UTF-8 JSON scenario file")
    explore = sub.add_parser("explore", help="enumerate bounded message-fault combinations over a base scenario")
    explore.add_argument("plan", help="path to a UTF-8 JSON plan file")
    replay = sub.add_parser("replay", help="recompute a simulation and field-compare it against a saved result")
    replay.add_argument("scenario", help="path to the UTF-8 JSON scenario file")
    replay.add_argument("result", help="path to a UTF-8 JSON file holding a simulate result")
    args = parser.parse_args(argv)

    if args.command == "version":
        print(__version__)
        return 0
    if args.command == "simulate":
        return _cmd_simulate(args.scenario)
    if args.command == "explore":
        return _cmd_explore(args.plan)
    if args.command == "replay":
        return _cmd_replay(args.scenario, args.result)

    parser.print_help()
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Bounded enumeration of message-fault combinations over a base scenario.

``explore`` reuses the deterministic simulator for every combination: it
never reads the wall clock, never uses randomness and never creates files,
so identical PLAN input produces byte-identical output.
"""

from __future__ import annotations

from itertools import combinations

from .simulate import ScenarioError, _Simulator, _require_int, parse_scenario

_PLAN_FIELDS = {
    "scenario",
    "candidates",
    "maxFaults",
    "maxCases",
    "minimizeFailures",
    "eventCandidates",
    "maxEventFaults",
}
_REQUIRED_PLAN_FIELDS = {"scenario", "candidates", "maxFaults", "maxCases"}
_EVENT_CANDIDATE_FIELDS = {"network", "node"}

# Reports whose violation lists decide a case's status. A report the scenario
# does not enable is absent from the result and plays no part in the verdict.
_CHECKED_REPORTS = (
    "electionSafety",
    "logMatching",
    "stateMachineSafety",
    "linearizability",
    "liveness",
)


def _failure_signature(result: dict) -> tuple[str, ...]:
    """Names of the enabled reports whose violation list is non-empty, in
    fixed check-priority order. Two cases share a failure signature exactly
    when they violate the same set of invariants."""
    return tuple(
        key
        for key in _CHECKED_REPORTS
        if key in result and result[key]["violations"]
    )


def _merged_config(
    scenario_raw: dict,
    candidates: list,
    event_candidates: list,
    event_selected: tuple[int, ...],
) -> dict:
    """Validate and normalize the scenario for one event combination: the
    base scenario with every message-fault candidate presented as its
    messageFaults and the selected events appended to the corresponding
    collections. Base entries keep their positions, so at one timestamp
    same-kind base events are processed before the selected candidates (in
    candidate-index order), and network events still precede node events."""
    merged = dict(scenario_raw)
    merged["messageFaults"] = candidates
    network = [
        event_candidates[i]["network"] for i in event_selected if "network" in event_candidates[i]
    ]
    node = [event_candidates[i]["node"] for i in event_selected if "node" in event_candidates[i]]
    if network or "faults" in merged:
        merged["faults"] = list(merged.get("faults", [])) + network
    if node or "nodeEvents" in merged:
        merged["nodeEvents"] = list(merged.get("nodeEvents", [])) + node
    return parse_scenario(merged)


def run_explore(raw: object) -> dict:
    """Validate a decoded JSON PLAN and run every fault combination."""
    if not isinstance(raw, dict):
        raise ScenarioError("plan must be a JSON object")
    unknown = sorted(set(raw) - _PLAN_FIELDS)
    if unknown:
        raise ScenarioError(f"unknown field(s): {', '.join(unknown)}")
    missing = sorted(_REQUIRED_PLAN_FIELDS - set(raw))
    if missing:
        raise ScenarioError(f"missing field(s): {', '.join(missing)}")

    has_event_candidates = "eventCandidates" in raw
    has_max_event_faults = "maxEventFaults" in raw
    if has_event_candidates != has_max_event_faults:
        raise ScenarioError(
            "eventCandidates and maxEventFaults must be provided together"
        )
    events_enabled = has_event_candidates

    minimize_failures = raw.get("minimizeFailures", False)
    if not isinstance(minimize_failures, bool):
        raise ScenarioError("minimizeFailures must be a boolean")

    scenario_raw = raw["scenario"]
    if not isinstance(scenario_raw, dict):
        raise ScenarioError("scenario must be a JSON object")
    if "messageFaults" in scenario_raw:
        raise ScenarioError("scenario must not contain messageFaults")

    candidates = raw["candidates"]
    if not isinstance(candidates, list):
        raise ScenarioError("candidates must be a list")
    if not candidates:
        raise ScenarioError("candidates must not be empty")

    max_faults = _require_int(raw["maxFaults"], "maxFaults", 0)
    if max_faults > len(candidates):
        raise ScenarioError("maxFaults must not exceed the number of candidates")
    max_cases = _require_int(raw["maxCases"], "maxCases", 1)

    event_candidates: list = []
    max_event_faults = 0
    if events_enabled:
        event_candidates = raw["eventCandidates"]
        if not isinstance(event_candidates, list):
            raise ScenarioError("eventCandidates must be a list")
        if not event_candidates:
            raise ScenarioError("eventCandidates must not be empty")
        for index, item in enumerate(event_candidates):
            label = f"eventCandidates[{index}]"
            if not isinstance(item, dict):
                raise ScenarioError(f"{label} must be an object")
            unknown = sorted(set(item) - _EVENT_CANDIDATE_FIELDS)
            if unknown:
                raise ScenarioError(
                    f"{label} has unknown field(s): {', '.join(unknown)}"
                )
            if len(set(item) & _EVENT_CANDIDATE_FIELDS) != 1:
                raise ScenarioError(
                    f"{label} must declare exactly one of network or node"
                )
        max_event_faults = _require_int(raw["maxEventFaults"], "maxEventFaults", 0)
        if max_event_faults > len(event_candidates):
            raise ScenarioError(
                "maxEventFaults must not exceed the number of event candidates"
            )

    # Validate the base scenario and every candidate rule with the original
    # scenario validation by presenting the candidates as its messageFaults;
    # this also rejects duplicated full selectors. Each normalized rule keeps
    # its candidate index in its "index" field.
    combined = dict(scenario_raw)
    combined["messageFaults"] = candidates
    config = parse_scenario(combined)
    rules = config["messageFaults"]

    # The empty combination comes first, then combinations of ascending size;
    # itertools.combinations yields index tuples in numeric lexicographic
    # order, and each tuple is ascending, so selected rules and events are
    # always injected in original candidate-index order.
    message_combos = [
        combo
        for size in range(max_faults + 1)
        for combo in combinations(range(len(candidates)), size)
    ]
    event_combos = [
        combo
        for size in range(max_event_faults + 1)
        for combo in combinations(range(len(event_candidates)), size)
    ]

    total = len(message_combos) * len(event_combos)
    if total > max_cases:
        raise ScenarioError(
            f"combination count {total} exceeds maxCases {max_cases}"
        )

    if events_enabled:
        # Every merged scenario is validated before any simulation runs:
        # first each event candidate on its own (in the base context, exactly
        # like the message-fault candidates above), then every enumerated
        # combination, whose appended events may jointly violate a constraint
        # such as crash/restart alternation.
        for index in range(len(event_candidates)):
            _merged_config(scenario_raw, candidates, event_candidates, (index,))
        event_configs = [
            _merged_config(scenario_raw, candidates, event_candidates, combo)
            for combo in event_combos
        ]
    else:
        event_configs = [config]

    # Message-fault combinations form the outer loop in their established
    # order; within each, the empty event combination comes first, then
    # event combinations of ascending size in numeric lexicographic order.
    cases = []
    # Only populated while minimizing: signature -> list of
    # (selected index tuple, selected event index tuple, caseId).
    # Minimization never runs extra simulations; it only references cases
    # enumerated here, so those references do not count against maxCases.
    by_signature: dict[
        tuple[str, ...], list[tuple[tuple[int, ...], tuple[int, ...], int]]
    ] = {}
    passed = 0
    case_id = 0
    for selected in message_combos:
        for event_index, event_selected in enumerate(event_combos):
            case_config = dict(event_configs[event_index])
            case_config["messageFaults"] = [rules[i] for i in selected]
            result = _Simulator(case_config).run()
            signature = _failure_signature(result)
            if signature:
                status = "failed"
            else:
                status = "passed"
                passed += 1
            case = {"caseId": case_id, "selected": list(selected)}
            if events_enabled:
                case["selectedEvents"] = list(event_selected)
            case["status"] = status
            case["result"] = result
            if minimize_failures and signature:
                by_signature.setdefault(signature, []).append(
                    (selected, event_selected, case_id)
                )
            cases.append(case)
            case_id += 1

    if minimize_failures:
        for case in cases:
            if case["status"] != "failed":
                continue
            signature = _failure_signature(case["result"])
            selected = tuple(case["selected"])
            selected_events = tuple(case.get("selectedEvents", ()))
            # Every minimizing combination must be reachable by deleting
            # candidates of both kinds from this case (sub-combinations of
            # its selected indices) and reproduce its exact failure
            # signature: a combination that passes or that only shows other
            # violations is never selected. The fewest total candidates win;
            # ties are broken by the numeric lexicographic order of the
            # selected index array, then of the selectedEvents array. The
            # case itself always qualifies.
            minimal_selected, minimal_events, minimal_case_id = min(
                (
                    entry
                    for entry in by_signature[signature]
                    if set(entry[0]).issubset(selected)
                    and set(entry[1]).issubset(selected_events)
                ),
                key=lambda entry: (len(entry[0]) + len(entry[1]), entry[0], entry[1]),
            )
            case["failureReports"] = list(signature)
            case["minimalSelected"] = list(minimal_selected)
            if events_enabled:
                case["minimalSelectedEvents"] = list(minimal_events)
            case["minimalCaseId"] = minimal_case_id

    return {
        "totalCases": len(cases),
        "passedCases": passed,
        "failedCases": len(cases) - passed,
        "cases": cases,
    }

"""Read-only replay verification of a saved ``simulate`` result.

``replay`` reruns the deterministic simulation on the original scenario and
compares the freshly computed result against the saved result field by field.
It never reads the wall clock, never uses randomness and never creates or
modifies files, so identical input produces byte-identical output.
"""

from __future__ import annotations

from .simulate import run_simulation


def _kind(value: object) -> str:
    """A JSON-level type tag. Booleans get their own tag so that ``true`` is
    never equal to the number 1, while ints and floats share ``number`` so
    that numbers compare by numeric value."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    return "object"


def _escape_token(token: str) -> str:
    """Escape one RFC 6901 reference token ('~' before '/')."""
    return token.replace("~", "~0").replace("/", "~1")


def _pointer(tokens: list[str]) -> str:
    if not tokens:
        return ""
    return "".join("/" + token for token in tokens)


def _first_difference(expected: object, actual: object, tokens: list[str]) -> str | None:
    """Return the RFC 6901 pointer of the first structural difference, or
    None when the two JSON values are equal.

    Arrays are compared by ascending index; objects recurse over the union of
    both sides' keys in ascending Unicode code-point order. A type or scalar
    difference ends the comparison at the current position; when an array
    prefix matches but the lengths differ, the pointer names the first
    missing index.
    """
    expected_kind = _kind(expected)
    actual_kind = _kind(actual)
    if expected_kind != actual_kind:
        return _pointer(tokens)

    if expected_kind in ("null", "bool", "number", "string"):
        if expected != actual:
            return _pointer(tokens)
        return None

    if expected_kind == "array":
        shared = min(len(expected), len(actual))
        for index in range(shared):
            found = _first_difference(expected[index], actual[index], tokens + [str(index)])
            if found is not None:
                return found
        if len(expected) != len(actual):
            return _pointer(tokens + [str(shared)])
        return None

    # Object: member order is irrelevant; visit the key union by Unicode code
    # point. A key present on only one side is itself the first difference.
    for key in sorted(set(expected) | set(actual)):
        token = _escape_token(key)
        if key not in expected or key not in actual:
            return _pointer(tokens + [token])
        found = _first_difference(expected[key], actual[key], tokens + [token])
        if found is not None:
            return found
    return None


def run_replay(scenario_raw: object, result_raw: object) -> dict:
    """Recompute the simulation for ``scenario_raw`` and compare it against
    the saved ``result_raw``.

    Returns ``{"status": "matched"}`` on equality, otherwise an object with
    ``status: "mismatched"``, the RFC 6901 pointer of the first difference,
    presence flags for both sides and the present value(s). Scenario
    validation errors propagate as :class:`ScenarioError` exactly as in
    ``simulate``.
    """
    expected = run_simulation(scenario_raw)

    path = _first_difference(expected, result_raw, [])
    if path is None:
        return {"status": "matched"}

    mismatch = {
        "status": "mismatched",
        "path": path,
        "expectedPresent": False,
        "actualPresent": False,
    }
    expected_value, actual_value = _value_at(expected, path), _value_at(result_raw, path)
    if expected_value is not _MISSING:
        mismatch["expectedPresent"] = True
        mismatch["expected"] = expected_value
    if actual_value is not _MISSING:
        mismatch["actualPresent"] = True
        mismatch["actual"] = actual_value
    return mismatch


class _Missing:
    """Sentinel for a pointer position absent on one side (distinct from a
    real JSON null, which is a present value)."""


_MISSING = _Missing()


def _value_at(root: object, path: str) -> object:
    """Resolve an RFC 6901 pointer produced by the comparison against one
    side. Returns the ``_MISSING`` sentinel when an object member or array
    index is absent."""
    if path == "":
        return root
    current = root
    for raw_token in path.split("/")[1:]:
        token = raw_token.replace("~1", "/").replace("~0", "~")
        if isinstance(current, dict):
            if token in current:
                current = current[token]
            else:
                return _MISSING
        elif isinstance(current, list) and token.isascii() and token.isdigit():
            index = int(token)
            if 0 <= index < len(current):
                current = current[index]
            else:
                return _MISSING
        else:
            return _MISSING
    return current

